window.TURATH_TK(66,{"e66.0":{"a":["سمّى اللّه ذلك اليوم الذي يفنى فيه هذا العالم بأسماء كثيرة، ومن أشهرها:","يوم القيامة، ورد هذا الاسم في سبعين آية من القرآن، كقوله تعالى:","﴿اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ الْقِيَامَةِ لَا رَيْبَ فِيهِ﴾ [سورة النساء: ٨٧].","اليوم الآخر: قال تعالى:","﴿إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ﴾ [التوبة: ١٨].","يوم البعث: قال تعالى:","﴿وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالْإِيمَانَ لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَىٰ يَوْمِ الْبَعْثِ فَهَذَا يَوْمُ الْبَعْثِ﴾ [سورة الروم: ٥٦].","يوم الدين: قال تعالى:","﴿وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ ۝ يَصْلَوْنَهَا يَوْمَ الدِّينِ﴾ [الانفطار: ١٤-١٥].","يوم الخروج: قال تعالى:","﴿يَوْمَ يَسْمَعُونَ الصَّيْحَةَ بِالْحَقِّ ذَٰلِكَ يَوْمُ الْخُرُوجِ﴾ [سورة ق: ٤٢].","يوم الوعيد: قال تعالى:","﴿وَنُفِخَ فِي الصُّورِ ذَٰلِكَ يَوْمُ الْوَعِيدِ﴾ [سورة ق: ٢٠].","يوم الخلود: قال اللّٰه عز وجل:","﴿ادْخُلُوهَا بِسَلَامٍ ذَٰلِكَ يَوْمُ الْخُلُودِ﴾ [سورة ق: ٣٤].","يوم الفصل: قال تعالى:","﴿هَذَا يَوْمُ الْفَصْلِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾ [الصافات: ٢١].","يوم الحسرة: قال تعالى:","﴿وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الْأَمْرُ وَهُمْ فِي غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ﴾ [سورة مريم: ٣٩].","يوم الحساب: قال تعالى:","﴿إِنَّ الَّذِينَ يَضِلُّونَ عَنْ سَبِيلِ اللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ بِمَا نَسُوا يَوْمَ الْحِسَابِ﴾ [سورة ص: ٢٦].","يوم الآزفة: قال تعالى:","﴿وَأَنْذِرْهُمْ يَوْمَ الْآزِفَةِ إِذِ الْقُلُوبُ لَدَى الْحَنَاجِرِ كَاظِمِينَ﴾ [غافر: ١٨].","يوم الجمع: قال تعالى:","﴿وَكَذَٰلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنْذِرَ يَوْمَ الْجَمْعِ لَا رَيْبَ فِيهِ﴾ [سورة الشورى: ٧].","يوم التلاق: قال تعالى:","﴿رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ يُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَىٰ مَنْ يَشَاءُ مِنْ عِبَادِهِ لِيُنْذِرَ يَوْمَ التَّلَاقِ﴾ [سورة غافر: ١٥].","يوم التناد: قال تعالى:","﴿وَيَا قَوْمِ إِنِّي أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ﴾ [سورة غافر: ٣٢].","يوم التغابن: قال تعالى:","﴿يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ ذَٰلِكَ يَوْمُ التَّغَابُنِ﴾ [التغابن: ٩].","الساعة: قال تعالى:","﴿إِنَّ السَّاعَةَ آتِيَةٌ أَكَادُ أُخْفِيهَا﴾ [طه: ١٥].","الغاشية: قال تعالى:","﴿هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ [الغاشية: ١].","القارعة: قال تعالى:","﴿الْقَارِعَةُ ۝ مَا الْقَارِعَةُ ۝ وَمَا أَدْرَاكَ مَا الْقَارِعَةُ﴾ [سورة القارعة: ١-٣].","الواقعة: قال تعالى:","﴿إِذَا وَقَعَتِ الْوَاقِعَةُ﴾ [سورة الواقعة: ١].","الحاقة: قال تعالى:","﴿الْحَاقَّةُ ۝ مَا الْحَاقَّةُ ۝ وَمَا أَدْرَاكَ مَا الْحَاقَّةُ﴾ [الحاقة: ١-٣].","قال القرطبي في التذكرة: “وكل ما عظم شأنه تعددت صفاته، وكثرت أسماؤه، وهذا مهيع كلام العرب، ألا ترى أن السيف لما عظم عندهم موضعه، وتأكد نفعه لديهم وموقعه، جمعوا له خمسمائة اسم، وله نظائر. فالقيامة لما عظم أمرها، وكثرت أهوالها، سماها اللّٰه تعالى في كتابه بأسماء عديدة، ووصفها بأوصاف كثيرة”.","والمهيع: من الطرق: البيّن، وجمعه: مهايع."],"b":["আল্লাহ সেই দিনকে—যেদিন এই দুনিয়া ধ্বংস হয়ে যাবে—অনেক নাম দিয়েছেন। এর মধ্যে প্রসিদ্ধ কয়েকটি হলো:","কিয়ামতের দিন: কুরআনের সত্তরটি আয়াতে এই নাম এসেছে। যেমন আল্লাহ তাআলা বলেন:","“আল্লাহ—তিনি ছাড়া কোনো উপাস্য নেই। অবশ্যই তিনি তোমাদের কিয়ামতের দিনে একত্র করবেন, এতে কোনো সন্দেহ নেই।”","[সূরা আন-নিসা ৪:৮৭]","শেষ দিবস: আল্লাহ তাআলা বলেন:","“আল্লাহর মসজিদসমূহ কেবল তারাই আবাদ করে, যারা আল্লাহ ও শেষ দিবসে ঈমান রাখে।”","[সূরা আত-তাওবাহ ৯:১৮]","কবর থেকে পুনরুত্থানের দিন: আল্লাহ তাআলা বলেন:","“যাদের জ্ঞান ও ঈমান দেওয়া হয়েছিল তারা বলবে, ‘তোমরা আল্লাহর বিধান অনুযায়ী পুনরুত্থানের দিন পর্যন্ত অবস্থান করেছিলে; আর এটাই সেই পুনরুত্থানের দিন।’”","[সূরা আর-রূম ৩০:৫৬]","প্রতিদানের দিন: আল্লাহ তাআলা বলেন:","“আর নিশ্চয়ই পাপাচারীরা জাহান্নামে থাকবে; তারা প্রতিদানের দিনে তাতে প্রবেশ করবে।”","[সূরা আল-ইনফিতার ৮২:১৪–১৫]","বেরিয়ে আসার দিন: আল্লাহ তাআলা বলেন:","“যেদিন তারা সত্যিকার সেই বিকট ধ্বনি শুনবে—সেদিনই হবে বেরিয়ে আসার দিন।”","[সূরা ক্বাফ ৫০:৪২]","সতর্কবাণীর দিন: আল্লাহ তাআলা বলেন:","“আর শিঙ্গায় ফুঁ দেওয়া হবে। এটাই সতর্কবাণীর দিন।”","[সূরা ক্বাফ ৫০:২০]","চিরস্থায়িত্বের দিন: আল্লাহ মহাপরাক্রমশালী ও মহিমান্বিত বলেন:","“শান্তিতে এতে প্রবেশ করো। এটাই চিরস্থায়িত্বের দিন।”","[সূরা ক্বাফ ৫০:৩৪]","ফয়সালা ও বিচ্ছেদের দিন: আল্লাহ তাআলা বলেন:","“এটাই সেই ফয়সালার দিন, যা তোমরা অস্বীকার করতে।”","[সূরা আস-সাফফাত ৩৭:২১]","আফসোসের দিন: আল্লাহ তাআলা বলেন:","“তাদের আফসোসের দিনের ব্যাপারে সতর্ক করুন, যখন সবকিছুর ফয়সালা হয়ে যাবে; অথচ তারা গাফিল এবং ঈমান আনে না।”","[সূরা মারইয়াম ১৯:৩৯]","হিসাবের দিন: আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা আল্লাহর পথ থেকে বিচ্যুত হয়, তাদের জন্য কঠিন শাস্তি রয়েছে, কারণ তারা হিসাবের দিন ভুলে গিয়েছিল।”","[সূরা সাদ ৩৮:২৬]","আসন্ন দিন: আল্লাহ তাআলা বলেন:","“তাদের সেই আসন্ন দিনের ব্যাপারে সতর্ক করুন, যখন হৃদয়সমূহ কণ্ঠনালী পর্যন্ত উঠে আসবে, দুঃখে দমবন্ধ অবস্থায়।”","[সূরা গাফির ৪০:১৮]","সমবেত হওয়ার দিন: আল্লাহ তাআলা বলেন:","“এভাবেই আমি আপনার প্রতি আরবি কুরআন ওহি করেছি, যাতে আপনি উম্মুল কুরা ও তার আশপাশের লোকদের সতর্ক করেন এবং সেই সমবেত হওয়ার দিনের ব্যাপারে সতর্ক করেন, যাতে কোনো সন্দেহ নেই।”","[সূরা আশ-শূরা ৪২:৭]","সাক্ষাতের দিন: আল্লাহ তাআলা বলেন:","“তিনি মর্যাদায় সুউচ্চ, আরশের অধিপতি; তিনি তাঁর বান্দাদের মধ্যে যাকে ইচ্ছা তাঁর আদেশে ওহি নাযিল করেন, যাতে সে সাক্ষাতের দিন সম্পর্কে সতর্ক করে।”","[সূরা গাফির ৪০:১৫]","ডাকাডাকির দিন: আল্লাহ তাআলা বলেন:","“হে আমার সম্প্রদায়! আমি তোমাদের জন্য ডাকাডাকির দিনের আশঙ্কা করি।”","[সূরা গাফির ৪০:৩২]","পারস্পরিক ক্ষতি ও লাভ প্রকাশের দিন: আল্লাহ তাআলা বলেন:","“যেদিন তিনি তোমাদের সমবেত হওয়ার দিনের জন্য একত্র করবেন—সেদিনই পারস্পরিক ক্ষতি ও লাভ প্রকাশের দিন।”","[সূরা আত-তাগাবুন ৬৪:৯]","কিয়ামত: আল্লাহ তাআলা বলেন:","“নিশ্চয়ই কিয়ামত আসন্ন। আমি প্রায় তা গোপন রাখতে চাই।”","[সূরা ত্বা-হা ২০:১৫]","আচ্ছন্নকারী ঘটনা: আল্লাহ তাআলা বলেন:","“আচ্ছন্নকারী ঘটনার সংবাদ কি আপনার কাছে পৌঁছেছে?”","[সূরা আল-গাশিয়াহ ৮৮:১]","প্রচণ্ড আঘাতকারী বিপর্যয়: আল্লাহ তাআলা বলেন:","“প্রচণ্ড আঘাতকারী বিপর্যয়! কী সেই প্রচণ্ড আঘাতকারী বিপর্যয়? আর কীসে আপনাকে জানাবে সেই প্রচণ্ড আঘাতকারী বিপর্যয় কী?”","[সূরা আল-কারি‘আহ ১০১:১–৩]","অবশ্যম্ভাবী ঘটনা: আল্লাহ তাআলা বলেন:","“যখন অবশ্যম্ভাবী ঘটনাটি সংঘটিত হবে।”","[সূরা আল-ওয়াকি‘আহ ৫৬:১]","অবধারিত বাস্তবতা: আল্লাহ তাআলা বলেন:","“অবধারিত বাস্তবতা! কী সেই অবধারিত বাস্তবতা? আর কীসে আপনাকে জানাবে সেই অবধারিত বাস্তবতা কী?”","[সূরা আল-হাক্কাহ ৬৯:১–৩]","আল-কুরতুবী ‘আত-তাযকিরাহ’-তে বলেছেন:","“যে বিষয় অত্যন্ত গুরুত্বপূর্ণ, তার বহু বর্ণনা ও বহু নাম হয়ে থাকে। আরবি ভাষায় এটি সুপরিচিত রীতি। তুমি কি দেখ না, আরবদের কাছে তরবারির গুরুত্ব ও উপকারিতা এত বেশি ছিল যে তারা এর পাঁচশ নাম দিয়েছিল? এরকম উদাহরণ অনেক।","তেমনি কিয়ামত যেহেতু এক মহাবিশাল ঘটনা এবং এর ভয়াবহতা বহুপ্রকার, তাই আল্লাহ তাআলা তাঁর কিতাবে এর বহু নাম দিয়েছেন এবং বহু গুণে একে বর্ণনা করেছেন।”","‘মাহইয়াআ’ শব্দের অর্থ সুস্পষ্ট রাস্তা; এর বহুবচন ‘মাহায়ি‘।’"],"e":["Allah has given the Day on which this world will perish many names. Among the most famous of them are:","The Day of Resurrection: This name occurs in seventy verses of the Qurʾān, such as the statement of Allah, the Exalted:","“Allah—there is no deity except Him. He will surely gather you together on the Day of Resurrection, about which there is no doubt.”","[al-Nisāʾ 4:87]","The Last Day: Allah, the Exalted, says:","“The mosques of Allah are only maintained by those who believe in Allah and the Last Day.”","[al-Tawbah 9:18]","The Day of Resurrection from the Graves: Allah, the Exalted, says:","“Those who were given knowledge and faith will say: ‘You remained, according to the decree of Allah, until the Day of Resurrection. So this is the Day of Resurrection.’”","[al-Rūm 30:56]","The Day of Recompense: Allah, the Exalted, says:","“And indeed, the wicked will be in Hell, entering it on the Day of Recompense.”","[al-Infiṭār 82:14-15]","The Day of Emergence: Allah, the Exalted, says:","“The Day they hear the Blast in truth—that will be the Day of Emergence.”","[Qāf 50:42]","The Day of the Threat: Allah, the Exalted, says:","“And the Trumpet will be blown. That is the Day of the Threat.”","[Qāf 50:20]","The Day of Eternity: Allah, Mighty and Majestic, says:","“Enter it in peace. This is the Day of Eternity.”","[Qāf 50:34]","The Day of Judgment and Separation: Allah, the Exalted, says:","“This is the Day of Judgment which you used to deny.”","[al-Ṣāffāt 37:21]","The Day of Regret: Allah, the Exalted, says:","“Warn them of the Day of Regret, when the matter will have been decided, while they are heedless and do not believe.”","[Maryam 19:39]","The Day of Reckoning: Allah, the Exalted, says:","“Indeed, those who stray from the path of Allah will have a severe punishment because they forgot the Day of Reckoning.”","[Ṣād 38:26]","The Approaching Day: Allah, the Exalted, says:","“Warn them of the Approaching Day, when hearts will be at the throats, choked with anguish.”","[Ghāfir 40:18]","The Day of Gathering: Allah, the Exalted, says:","“Thus We have revealed to you an Arabic Qurʾān so that you may warn the Mother of Cities and those around it, and warn of the Day of Gathering, about which there is no doubt.”","[al-Shūrā 42:7]","The Day of Meeting: Allah, the Exalted, says:","“Exalted in rank, Owner of the Throne, He sends the revelation by His command to whomever He wills among His servants, so that he may warn of the Day of Meeting.”","[Ghāfir 40:15]","The Day of Calling Out: Allah, the Exalted, says:","“O my people, I fear for you the Day of Calling Out.”","[Ghāfir 40:32]","The Day of Mutual Loss and Gain: Allah, the Exalted, says:","“The Day He gathers you for the Day of Gathering—that is the Day of Mutual Loss and Gain.”","[al-Taghābun 64:9]","The Hour: Allah, the Exalted, says:","“Indeed, the Hour is coming. I almost conceal it.”","[Ṭā Hā 20:15]","The Overwhelming Event: Allah, the Exalted, says:","“Has there reached you the account of the Overwhelming Event?”","[al-Ghāshiyah 88:1]","The Striking Calamity: Allah, the Exalted, says:","“The Striking Calamity! What is the Striking Calamity? And what can make you know what the Striking Calamity is?”","[al-Qāriʿah 101:1-3]","The Inevitable Event: Allah, the Exalted, says:","“When the Inevitable Event occurs.”","[al-Wāqiʿah 56:1]","The Inevitable Reality: Allah, the Exalted, says:","“The Inevitable Reality! What is the Inevitable Reality? And what can make you know what the Inevitable Reality is?”","[al-Ḥāqqah 69:1-3]","Al-Qurṭubī said in al-Tadhkirah:","“Everything of tremendous importance acquires numerous descriptions and many names. This is the well-trodden way of Arabic speech. Do you not see that because the sword held such an important place among the Arabs, and because of its great usefulness and significance to them, they gave it five hundred names? There are many similar examples.","Likewise, because the Resurrection is an immense event and its terrors are many, Allah, the Exalted, has given it numerous names in His Book and described it with many attributes.”","The word “mahyaʿ” means a clear road; its plural is “mahāyiʿ.”"]},"n16129":{"a":["قال تعالى:","﴿يَسْأَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ رَبِّي لَا يُجَلِّيهَا لِوَقْتِهَا إِلَّا هُوَ ثَقُلَتْ فِي السَّمَاوَاتِ وَالْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْأَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِنْدَ اللَّهِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ﴾ [سورة الأعراف: ١٨٧].","وقال تعالى:","﴿هَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ أَنْ تَأْتِيَهُمْ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ﴾ [سورة الزخرف: ٦٦]."],"b":["আল্লাহ তাআলা বলেন:","“তারা আপনাকে কিয়ামত সম্পর্কে জিজ্ঞেস করে, ‘তা কখন আসবে?’ বলুন, ‘এর জ্ঞান তো কেবল আমার রবের কাছেই। তিনি ছাড়া কেউ এর সময় প্রকাশ করবেন না। তা আসমানসমূহ ও যমীনের ওপর ভারী। তা তোমাদের কাছে কেবল আকস্মিকভাবেই আসবে।’ তারা আপনাকে এমনভাবে জিজ্ঞেস করে যেন আপনি এ বিষয়ে গভীরভাবে অবগত। বলুন, ‘এর জ্ঞান তো কেবল আল্লাহর কাছেই, কিন্তু অধিকাংশ মানুষ জানে না।’”","[সূরা আল-আ‘রাফ ৭:১৮৭]","আর তিনি তাআলা বলেন:","“তারা কি কেবল এ অপেক্ষায় আছে যে কিয়ামত তাদের ওপর আকস্মিকভাবে এসে পড়বে, অথচ তারা টেরও পাবে না?”","[সূরা আয-যুখরুফ ৪৩:৬৬]"],"e":["Allah, the Exalted, says:","“They ask you about the Hour: ‘When will it arrive?’ Say: ‘Knowledge of it is only with my Lord. None will reveal its time except Him. It weighs heavily upon the heavens and the earth. It will not come upon you except suddenly.’ They ask you as though you were well informed about it. Say: ‘Knowledge of it is only with Allah, but most people do not know.’”","[al-Aʿrāf 7:187]","And He, the Exalted, says:","“Are they waiting for anything except that the Hour should come upon them suddenly while they are unaware?”","[al-Zukhruf 43:66]"]},"n16133":{"a":["قال تعالى:","﴿وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا ۝ قُلْ كُونُوا حِجَارَةً أَوْ حَدِيدًا ۝ أَوْ خَلْقًا مِمَّا يَكْبُرُ فِي صُدُورِكُمْ فَسَيَقُولُونَ مَنْ يُعِيدُنَا قُلِ الَّذِي فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰ أَنْ يَكُونَ قَرِيبًا﴾ [سورة الإسراء: ٤٩-٥١]."],"b":["আল্লাহ তাআলা বলেন:","“তারা বলে, ‘যখন আমরা হাড় ও চূর্ণবিচূর্ণ অবশেষে পরিণত হব, তখনও কি আমাদের নতুন সৃষ্টি হিসেবে পুনরুত্থিত করা হবে?’ বলুন, ‘তোমরা পাথর হয়ে যাও অথবা লোহা, কিংবা এমন কোনো সৃষ্টি যা তোমাদের ধারণায় আরও কঠিন।’ তখন তারা বলবে, ‘কে আমাদের পুনরায় ফিরিয়ে আনবে?’ বলুন, ‘যিনি তোমাদের প্রথমবার সৃষ্টি করেছেন।’ তখন তারা আপনার দিকে মাথা নেড়ে বলবে, ‘তা কখন হবে?’ বলুন, ‘হয়তো তা নিকটবর্তী।’”","[সূরা আল-ইসরা ১৭:৪৯–৫১]"],"e":["Allah, the Exalted, says:","“They say: ‘When we have become bones and crumbled remains, will we really be resurrected as a new creation?’ Say: ‘Be stones or iron, or any creation you consider even greater.’ Then they will say: ‘Who will restore us?’ Say: ‘The One who created you the first time.’ They will shake their heads at you and say: ‘When will that be?’ Say: ‘Perhaps it is near.’”","[al-Isrāʾ 17:49-51]"]},"n16134":{"a":["قال تعالى:","﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ﴾ [سورة الزمر: ٦٨].","وقال تعالى:","﴿وَيَوْمَ يُنْفَخُ فِي الصُّورِ فَفَزِعَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ وَكُلٌّ أَتَوْهُ دَاخِرِينَ﴾ [سورة النمل: ٨٧].","وقال تعالى:","﴿فَإِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌ ۝ وَحُمِلَتِ الْأَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةً وَاحِدَةً ۝ فَيَوْمَئِذٍ وَقَعَتِ الْوَاقِعَةُ ۝ وَانْشَقَّتِ السَّمَاءُ فَهِيَ يَوْمَئِذٍ وَاهِيَةٌ﴾ [سورة الحاقة: ١٣-١٦]."],"b":["আল্লাহ তাআলা বলেন:","“শিঙ্গায় ফুঁ দেওয়া হবে; ফলে আসমানসমূহে ও যমীনে যারা আছে তারা সবাই অচেতন হয়ে পড়বে, আল্লাহ যাকে ইচ্ছা করেন সে ছাড়া। তারপর আবার তাতে ফুঁ দেওয়া হবে, তখন হঠাৎ তারা দাঁড়িয়ে তাকাতে থাকবে।”","[সূরা আয-যুমার ৩৯:৬৮]","আর তিনি তাআলা বলেন:","“যেদিন শিঙ্গায় ফুঁ দেওয়া হবে, সেদিন আসমানসমূহ ও যমীনে যারা আছে তারা সবাই আতঙ্কিত হবে, আল্লাহ যাকে ইচ্ছা করেন সে ছাড়া; আর সবাই তাঁর কাছে বিনীত অবস্থায় উপস্থিত হবে।”","[সূরা আন-নামল ২৭:৮৭]","আর তিনি তাআলা বলেন:","“যখন শিঙ্গায় একবার ফুঁ দেওয়া হবে, আর যমীন ও পাহাড়সমূহ তুলে নিয়ে এক আঘাতে চূর্ণ করা হবে, তখন সেদিন অবশ্যম্ভাবী ঘটনাটি সংঘটিত হবে; আর আসমান বিদীর্ণ হয়ে যাবে, কারণ সেদিন তা দুর্বল হয়ে পড়বে।”","[সূরা আল-হাক্কাহ ৬৯:১৩–১৬]"],"e":["Allah, the Exalted, says:","“The Trumpet will be blown, and everyone in the heavens and everyone on the earth will fall unconscious, except whomever Allah wills. Then it will be blown again, and suddenly they will be standing, looking on.”","[al-Zumar 39:68]","And He, the Exalted, says:","“On the Day the Trumpet is blown, everyone in the heavens and the earth will be terrified except whomever Allah wills, and all will come before Him humbled.”","[al-Naml 27:87]","And He, the Exalted, says:","“When the Trumpet is blown with a single blast, and the earth and mountains are lifted and crushed with one crushing blow, then on that Day the Inevitable Event will occur, and the heaven will split apart, for on that Day it will be frail.”","[al-Ḥāqqah 69:13-16]"]},"n16137":{"a":["قال اللّٰه تعالى:","﴿وَنُفِخَ فِي الصُّورِ فَإِذَا هُمْ مِنَ الْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنْسِلُونَ ۝ قَالُوا يَا وَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا هَذَا مَا وَعَدَ الرَّحْمَٰنُ وَصَدَقَ الْمُرْسَلُونَ ۝ إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَدَيْنَا مُحْضَرُونَ﴾ [سورة يس: ٥١-٥٣]."],"b":["আল্লাহ তাআলা বলেন:","“শিঙ্গায় ফুঁ দেওয়া হবে, তখন হঠাৎ তারা কবর থেকে তাদের রবের দিকে দ্রুত ছুটে যাবে। তারা বলবে, ‘হায় আমাদের দুর্ভোগ! আমাদের শয়নস্থান থেকে কে আমাদের উঠাল?’ এটাই তো ছিল যা পরম দয়ালু প্রতিশ্রুতি দিয়েছিলেন, আর রাসূলগণ সত্যই বলেছিলেন। তা কেবল একটি বিকট ধ্বনি হবে, আর তখনই সবাইকে আমার সামনে উপস্থিত করা হবে।”","[সূরা ইয়াসীন ৩৬:৫১–৫৩]"],"e":["Allah, the Exalted, says:","“The Trumpet will be blown, and suddenly they will rush from the graves toward their Lord. They will say: ‘Woe to us! Who has raised us from our resting place?’ This is what the Most Merciful had promised, and the messengers spoke the truth. It will be only one Blast, and suddenly they will all be brought before Us.”","[Yā Sīn 36:51-53]"]},"n16149":{"a":["قال اللّٰه تعالى:","﴿قُلْ إِنَّ الْأَوَّلِينَ وَالْآخِرِينَ ۝ لَمَجْمُوعُونَ إِلَىٰ مِيقَاتِ يَوْمٍ مَعْلُومٍ﴾ [الواقعة: ٤٩-٥٠].","وقال تعالى:","﴿إِنْ كُلُّ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ إِلَّا آتِي الرَّحْمَٰنِ عَبْدًا ۝ لَقَدْ أَحْصَاهُمْ وَعَدَّهُمْ عَدًّا ۝ وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْدًا﴾ [سورة مريم: ٩٣-٩٥]."],"b":["আল্লাহ তাআলা বলেন:","“বলুন, নিশ্চয়ই পূর্ববর্তী ও পরবর্তী সকলকেই এক নির্ধারিত দিনের নির্দিষ্ট সময়ে একত্র করা হবে।”","[সূরা আল-ওয়াকি‘আহ ৫৬:৪৯–৫০]","আর তিনি তাআলা বলেন:","“আসমানসমূহ ও যমীনে এমন কেউ নেই যে পরম দয়ালুর কাছে বান্দা হিসেবে উপস্থিত হবে না। তিনি অবশ্যই তাদের গণনা করেছেন এবং নিখুঁতভাবে সংখ্যা নির্ধারণ করেছেন। আর কিয়ামতের দিনে তাদের প্রত্যেকেই তাঁর কাছে একাকী উপস্থিত হবে।”","[সূরা মারইয়াম ১৯:৯৩–৯৫]"],"e":["Allah, the Exalted, says:","“Say: Indeed, the former and the later peoples will surely all be gathered for the appointed time of a known Day.”","[al-Wāqiʿah 56:49-50]","And He, the Exalted, says:","“There is no one in the heavens and the earth except that he will come to the Most Merciful as a servant. He has certainly counted them and numbered them precisely. And every one of them will come to Him individually on the Day of Resurrection.”","[Maryam 19:93-95]"]},"n16156":{"a":["قال تعالى:","﴿وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُمْ مُسْوَدَّةٌ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّرِينَ﴾ [سورة الزمر: ٦٠]."],"b":["আল্লাহ তাআলা বলেন:","“কিয়ামতের দিনে আপনি তাদের দেখবেন যারা আল্লাহ সম্পর্কে মিথ্যা বলেছিল—তাদের মুখ কালো হয়ে যাবে। অহংকারীদের জন্য কি জাহান্নামে আবাসস্থল নেই?”","[সূরা আয-যুমার ৩৯:৬০]"],"e":["Allah, the Exalted, says:","“On the Day of Resurrection you will see those who lied about Allah with their faces blackened. Is there not in Hell a dwelling place for the arrogant?”","[al-Zumar 39:60]"]},"n16168":{"a":["قال تعالى:","﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ ۝ يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّا أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَارَىٰ وَمَا هُمْ بِسُكَارَىٰ وَلَٰكِنَّ عَذَابَ اللَّهِ شَدِيدٌ﴾ [سورة الحج: ١-٢].","وقال تعالى:","﴿فَكَيْفَ تَتَّقُونَ إِنْ كَفَرْتُمْ يَوْمًا يَجْعَلُ الْوِلْدَانَ شِيبًا ۝ السَّمَاءُ مُنْفَطِرٌ بِهِ كَانَ وَعْدُهُ مَفْعُولًا﴾ [سورة المزمل: ١٧-١٨].","وقال تعالى:","﴿يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ ۝ وَأُمِّهِ وَأَبِيهِ ۝ وَصَاحِبَتِهِ وَبَنِيهِ ۝ لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ﴾ [سورة عبس: ٣٤-٣٧].","وقال تعالى:","﴿يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ ۝ وَتَرَى الْمُجْرِمِينَ يَوْمَئِذٍ مُقَرَّنِينَ فِي الْأَصْفَادِ ۝ سَرَابِيلُهُمْ مِنْ قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ النَّارُ ۝ لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ مَا كَسَبَتْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾ [سورة إبراهيم: ٤٨-٥١].","وقال تعالى:","﴿وَيَسْأَلُونَكَ عَنِ الْجِبَالِ فَقُلْ يَنْسِفُهَا رَبِّي نَسْفًا ۝ فَيَذَرُهَا قَاعًا صَفْصَفًا ۝ لَا تَرَىٰ فِيهَا عِوَجًا وَلَا أَمْتًا﴾ [سورة طه: ١٠٥-١٠٧]."],"b":["আল্লাহ তাআলা বলেন:","“হে মানুষ! তোমরা তোমাদের রবকে ভয় করো। নিশ্চয়ই কিয়ামতের কম্পন এক ভয়াবহ বিষয়। যেদিন তোমরা তা দেখবে, প্রত্যেক স্তন্যদানকারী মা তার দুগ্ধপোষ্য শিশুকে ভুলে যাবে, প্রত্যেক গর্ভবতী তার গর্ভপাত করবে, আর মানুষকে তুমি মাতাল মনে করবে—অথচ তারা মাতাল নয়; বরং আল্লাহর শাস্তি অত্যন্ত কঠিন।”","[সূরা আল-হজ্জ ২২:১–২]","আর তিনি তাআলা বলেন:","“তোমরা যদি কুফর করো, তবে কীভাবে নিজেদের সেই দিন থেকে রক্ষা করবে যা শিশুদের চুল পাকা করে দেবে? আসমানও তার কারণে বিদীর্ণ হয়ে যাবে। তাঁর প্রতিশ্রুতি অবশ্যই বাস্তবায়িত হবে।”","[সূরা আল-মুযযাম্মিল ৭৩:১৭–১৮]","আর তিনি তাআলা বলেন:","“সেদিন মানুষ তার ভাই থেকে পালাবে, তার মা ও পিতা থেকে, তার স্ত্রী ও সন্তানদের থেকেও। সেদিন তাদের প্রত্যেকের নিজেরই এমন ব্যস্ততা থাকবে যা তাকে অন্য সবকিছু থেকে বিমুখ রাখবে।”","[সূরা আবাসা ৮০:৩৪–৩৭]","আর তিনি তাআলা বলেন:","“যেদিন এই যমীন অন্য যমীনে এবং আসমানসমূহও পরিবর্তিত হবে, আর সবাই একক, পরাক্রমশালী আল্লাহর সামনে উপস্থিত হবে। সেদিন আপনি অপরাধীদের শৃঙ্খলে বাঁধা অবস্থায় দেখবেন। তাদের পোশাক হবে আলকাতরার, আর আগুন তাদের মুখ ঢেকে ফেলবে—যাতে আল্লাহ প্রত্যেক প্রাণকে তার উপার্জনের প্রতিফল দেন। নিশ্চয়ই আল্লাহ দ্রুত হিসাব গ্রহণকারী।”","[সূরা ইবরাহীম ১৪:৪৮–৫১]","আর তিনি তাআলা বলেন:","“তারা আপনাকে পাহাড়সমূহ সম্পর্কে জিজ্ঞেস করে। বলুন, ‘আমার রব সেগুলো সম্পূর্ণ ছিন্নভিন্ন করে ছড়িয়ে দেবেন; ফলে যমীনকে সমতল, অনুর্বর প্রান্তরে পরিণত করবেন। সেখানে তুমি কোনো নিচু বা উঁচু স্থান দেখতে পাবে না।’”","[সূরা ত্বা-হা ২০:১০৫–১০৭]"],"e":["Allah, the Exalted, says:","“O mankind, fear your Lord. Indeed, the convulsion of the Hour is a tremendous thing. On the Day you see it, every nursing mother will forget the child she was nursing, every pregnant woman will miscarry her pregnancy, and you will see the people appearing intoxicated though they are not intoxicated; rather, the punishment of Allah is severe.”","[al-Ḥajj 22:1-2]","And He, the Exalted, says:","“How then will you protect yourselves, if you disbelieve, from a Day that will turn children gray-haired? The heaven will split apart because of it. His promise will surely be fulfilled.”","[al-Muzzammil 73:17-18]","And He, the Exalted, says:","“On that Day a person will flee from his brother, and from his mother and father, and from his wife and children. Every person among them on that Day will have enough concern of his own to occupy him.”","[ʿAbasa 80:34-37]","And He, the Exalted, says:","“On the Day the earth will be replaced by another earth, and the heavens as well, and all will appear before Allah, the One, the Overpowering. You will see the criminals on that Day bound together in chains. Their garments will be of pitch, and the Fire will cover their faces, so that Allah may repay every soul for what it earned. Indeed, Allah is swift in reckoning.”","[Ibrāhīm 14:48-51]","And He, the Exalted, says:","“They ask you about the mountains. Say: ‘My Lord will utterly scatter them, leaving the earth a level, barren plain. You will see in it neither depression nor elevation.’”","[Ṭā Hā 20:105-107]"]},"n16170":{"a":["قال تعالى:","﴿يَوْمَ نَطْوِي السَّمَاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ﴾ [الأنبياء: ١٠٤].","وقال تعالى:","﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ﴾ [سورة الزمر: ٦٧]."],"b":["আল্লাহ তাআলা বলেন:","“যেদিন আমি আসমানকে লিখিত পত্র গুটিয়ে নেওয়ার মতো গুটিয়ে নেব। যেভাবে আমি প্রথম সৃষ্টি শুরু করেছিলাম, সেভাবেই তা পুনরাবৃত্তি করব—এটি আমার ওপর অবধারিত প্রতিশ্রুতি। নিশ্চয়ই আমি তা করব।”","[সূরা আল-আম্বিয়া ২১:১০৪]","আর তিনি তাআলা বলেন:","“তারা আল্লাহকে যথাযথভাবে মর্যাদা দেয়নি। কিয়ামতের দিনে সমগ্র যমীন থাকবে তাঁর মুঠিতে এবং আসমানসমূহ থাকবে তাঁর ডান হাতে গুটানো। তারা যা শরিক করে, তিনি তা থেকে পবিত্র ও বহু ঊর্ধ্বে।”","[সূরা আয-যুমার ৩৯:৬৭]"],"e":["Allah, the Exalted, says:","“On the Day We will fold the heaven like the folding of a scroll for writings. Just as We began the first creation, We will repeat it—a promise binding upon Us. We will surely do it.”","[al-Anbiyāʾ 21:104]","And He, the Exalted, says:","“They did not estimate Allah with the estimation due to Him. The whole earth will be in His grasp on the Day of Resurrection, and the heavens will be folded in His right hand. Glorified and Exalted is He above what they associate with Him.”","[al-Zumar 39:67]"]},"n16174":{"a":["قال تعالى:","﴿إِذَا الشَّمْسُ كُوِّرَتْ﴾ [التكوير: ١]."],"b":["আল্লাহ তাআলা বলেন:","“যখন সূর্যকে গুটিয়ে নেওয়া হবে।”","[সূরা আত-তাকভীর ৮১:১]"],"e":["Allah, the Exalted, says:","“When the sun is folded up.”","[al-Takwīr 81:1]"]},"n16178":{"a":["الأصل فيه قوله تعالى:","﴿وَكَمْ مِنْ مَلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللَّهُ لِمَنْ يَشَاءُ وَيَرْضَىٰ﴾ [سورة النجم: ٢٦].","والشفاعة لا بد لها من اجتماع شرطين:","الأول: إذن اللّٰه تعالى في الشفاعة للشافع.","الثاني: رضاه عن المشفوع له.","وعلى هذا فالمشركون لا نصيب لهم من شفاعة الشافعين، وقد صدوا على أنفسهم رحمة أرحم الراحمين.","أنواع الشفاعة:","١- شفاعته ﷺ العامة في أهل الموقف ليريحهم من مقامهم"],"b":["এর ভিত্তি হলো আল্লাহ তাআলার বাণী:","“আসমানসমূহে কত ফেরেশতা রয়েছে, যাদের শাফা‘আত কোনো উপকারে আসে না—যতক্ষণ না আল্লাহ যাকে ইচ্ছা এবং যার প্রতি সন্তুষ্ট হন, তার জন্য অনুমতি দেন।”","[সূরা আন-নাজম ৫৩:২৬]","শাফা‘আতের জন্য দুটি শর্ত পূরণ হওয়া আবশ্যক:","প্রথমত: আল্লাহ তাআলা শাফা‘আতকারীকে শাফা‘আতের অনুমতি দেবেন।","দ্বিতীয়ত: যার জন্য শাফা‘আত করা হবে, আল্লাহ তার প্রতি সন্তুষ্ট হবেন।","সুতরাং মুশরিকদের জন্য শাফা‘আতকারীদের শাফা‘আতে কোনো অংশ থাকবে না। তারা নিজেরাই নিজেদের পরম দয়ালুদের মধ্যে সর্বাধিক দয়ালু আল্লাহর রহমত থেকে বঞ্চিত করেছে।","শাফা‘আতের প্রকারসমূহ:","১ — সমবেত মানুষের জন্য তাঁর ﷺ সাধারণ শাফা‘আত, যাতে তাদের দীর্ঘ প্রতীক্ষার কষ্ট লাঘব হয়।"],"e":["The basis for this is the statement of Allah, the Exalted:","“How many angels are there in the heavens whose intercession is of no benefit whatsoever except after Allah gives permission to whom He wills and is pleased with.”","[al-Najm 53:26]","Intercession requires two conditions to be fulfilled:","First: Allah, the Exalted, must give the intercessor permission to intercede.","Second: Allah must be pleased with the one on whose behalf the intercession is made.","Accordingly, the polytheists will have no share in the intercession of the intercessors. They have barred themselves from the mercy of the Most Merciful of those who show mercy.","Types of intercession:","1 – His ﷺ General Intercession for the People of the Gathering, to Relieve Them from Their Standing"]},"n16202":{"a":["قال تعالى:","﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ [سورة التكاثر: ٨]."],"b":["আল্লাহ তাআলা বলেন:","“তারপর সেদিন অবশ্যই তোমাদের নিয়ামতসমূহ সম্পর্কে জিজ্ঞেস করা হবে।”","[সূরা আত-তাকাসুর ১০২:৮]"],"e":["Allah, the Exalted, says:","“Then, on that Day, you will surely be questioned about the blessings.”","[al-Takāthur 102:8]"]},"n16205":{"a":["قال تعالى:","﴿وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ [البقرة: ١٤٣]."],"b":["আল্লাহ তাআলা বলেন:","“এভাবেই আমি তোমাদের একটি ন্যায়পরায়ণ ও ভারসাম্যপূর্ণ উম্মাহ বানিয়েছি, যাতে তোমরা মানুষের ওপর সাক্ষী হও এবং রাসূল তোমাদের ওপর সাক্ষী হন।”","[সূরা আল-বাকারাহ ২:১৪৩]"],"e":["Allah, the Exalted, says:","“Thus We have made you a just and balanced nation so that you may be witnesses over mankind and the Messenger may be a witness over you.”","[al-Baqarah 2:143]"]},"n16208":{"a":["قال تعالى:","﴿يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ﴾ [النور: ٢٤].","وقال تعالى:","﴿حَتَّىٰ إِذَا مَا جَاءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُمْ بِمَا كَانُوا يَعْمَلُونَ ۝ وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنَا قَالُوا أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ﴾ [فصلت: ٢٠-٢١]."],"b":["আল্লাহ তাআলা বলেন:","“যেদিন তাদের জিহ্বা, হাত ও পা তাদের বিরুদ্ধে তাদের কৃতকর্ম সম্পর্কে সাক্ষ্য দেবে।”","[সূরা আন-নূর ২৪:২৪]","আর তিনি তাআলা বলেন:","“অবশেষে যখন তারা সেখানে পৌঁছবে, তখন তাদের কান, চোখ ও চামড়া তাদের কৃতকর্ম সম্পর্কে তাদের বিরুদ্ধে সাক্ষ্য দেবে। তারা তাদের চামড়াকে বলবে, ‘তোমরা আমাদের বিরুদ্ধে সাক্ষ্য দিলে কেন?’ তারা বলবে, ‘আল্লাহ আমাদের কথা বলিয়েছেন, যিনি সবকিছুকে কথা বলান। তিনিই তোমাদের প্রথমবার সৃষ্টি করেছেন এবং তাঁর কাছেই তোমাদের ফিরিয়ে নেওয়া হচ্ছে।’”","[সূরা ফুসসিলাত ৪১:২০–২১]"],"e":["Allah, the Exalted, says:","“On the Day when their tongues, their hands, and their feet will testify against them concerning what they used to do.”","[al-Nūr 24:24]","And He, the Exalted, says:","“Until, when they reach it, their hearing, their sight, and their skins will testify against them concerning what they used to do. They will say to their skins: ‘Why did you testify against us?’ They will reply: ‘Allah, who gives speech to everything, has made us speak. He created you the first time, and to Him you are being returned.’”","[Fuṣṣilat 41:20-21]"]},"e66.38":{"a":["قال تعالى:","﴿وَوُضِعَ الْكِتَابُ فَتَرَى الْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَالِ هَٰذَا الْكِتَابِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّا أَحْصَاهَا وَوَجَدُوا مَا عَمِلُوا حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا﴾ [سورة الكهف: ٤٩].","وقال تعالى:","﴿وَكُلَّ إِنسَانٍ أَلْزَمْنَاهُ طَائِرَهُ فِي عُنُقِهِ وَنُخْرِجُ لَهُ يَوْمَ الْقِيَامَةِ كِتَابًا يَلْقَاهُ مَنْشُورًا ۝ اقْرَأْ كِتَابَكَ كَفَىٰ بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَسِيبًا﴾ [سورة الإسراء: ١٣-١٤].","وقال تعالى:","﴿فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَيَقُولُ هَاؤُمُ اقْرَءُوا كِتَابِيَهْ ۝ إِنِّي ظَنَنْتُ أَنِّي مُلَاقٍ حِسَابِيَهْ ۝ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ﴾","إلى قوله:","﴿وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِشِمَالِهِ فَيَقُولُ يَا لَيْتَنِي لَمْ أُوتَ كِتَابِيَهْ ۝ وَلَمْ أَدْرِ مَا حِسَابِيَهْ ۝ يَا لَيْتَهَا كَانَتِ الْقَاضِيَةَ ۝ مَا أَغْنَىٰ عَنِّي مَالِيَهْ ۝ هَلَكَ عَنِّي سُلْطَانِيَهْ﴾ [سورة الحاقة: ١٩-٢٩].","وقال تعالى:","﴿فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ ۝ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا ۝ وَيَنْقَلِبُ إِلَىٰ أَهْلِهِ مَسْرُورًا ۝ وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ ۝ فَسَوْفَ يَدْعُو ثُبُورًا ۝ وَيَصْلَىٰ سَعِيرًا ۝ إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا ۝ إِنَّهُ ظَنَّ أَنْ لَنْ يَحُورَ ۝ بَلَىٰ إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا﴾ [سورة الانشقاق: ٧-١٥]."],"b":["আল্লাহ তাআলা বলেন:","“আমলনামা সামনে রাখা হবে; তখন আপনি অপরাধীদের দেখবেন, তাতে যা আছে সে কারণে তারা আতঙ্কিত। তারা বলবে, ‘হায় আমাদের দুর্ভোগ! এ কেমন আমলনামা, যা ছোট-বড় কিছুই বাদ দেয়নি, সবকিছু গণনা করে রেখেছে!’ তারা যা করেছে সবই সামনে উপস্থিত পাবে; আর আপনার রব কারও প্রতি জুলুম করেন না।”","[সূরা আল-কাহফ ১৮:৪৯]","আর তিনি তাআলা বলেন:","“আমি প্রত্যেক মানুষের কর্ম তার গলায় বেঁধে দিয়েছি; আর কিয়ামতের দিনে আমি তার জন্য এমন এক আমলনামা বের করব, যা সে খোলা অবস্থায় পাবে। ‘তোমার আমলনামা পড়ো। আজ তোমার নিজের হিসাব গ্রহণের জন্য তুমিই যথেষ্ট।’”","[সূরা আল-ইসরা ১৭:১৩–১৪]","আর তিনি তাআলা বলেন:","“যার আমলনামা তার ডান হাতে দেওয়া হবে, সে বলবে, ‘নাও, আমার আমলনামা পড়ো! আমি তো নিশ্চিত ছিলাম যে আমার হিসাবের মুখোমুখি হব।’ অতএব সে থাকবে সন্তোষজনক জীবনে…”","এরপর তাঁর বাণী পর্যন্ত:","“আর যার আমলনামা তার বাম হাতে দেওয়া হবে, সে বলবে, ‘হায়! যদি আমাকে আমার আমলনামা না দেওয়া হতো এবং আমি যদি আমার হিসাব জানতেই না পারতাম! হায়! মৃত্যুই যদি সবকিছুর সমাপ্তি হতো! আমার সম্পদ আমার কোনো উপকারে আসেনি। আমার কর্তৃত্বও আমার কাছ থেকে বিলীন হয়ে গেছে।’”","[সূরা আল-হাক্কাহ ৬৯:১৯–২৯]","আর তিনি তাআলা বলেন:","“যার আমলনামা তার ডান হাতে দেওয়া হবে, তার সহজ হিসাব নেওয়া হবে এবং সে আনন্দিত হয়ে তার আপনজনদের কাছে ফিরে যাবে। কিন্তু যার আমলনামা তার পেছন দিক থেকে দেওয়া হবে, সে ধ্বংস কামনা করবে এবং জ্বলন্ত আগুনে প্রবেশ করবে। নিশ্চয়ই সে তার পরিবারের মাঝে আনন্দে ছিল। সে মনে করেছিল যে সে কখনো ফিরে আসবে না। অবশ্যই! নিশ্চয়ই তার রব সবসময় তাকে দেখছিলেন।”","[সূরা আল-ইনশিকাক ৮৪:৭–১৫]"],"e":["Allah, the Exalted, says:","“The record will be placed, and you will see the criminals fearful of what is in it. They will say: ‘Woe to us! What is this record that leaves neither a small deed nor a great one except that it has counted it?’ They will find everything they did present before them, and your Lord wrongs no one.”","[al-Kahf 18:49]","And He, the Exalted, says:","“We have fastened every person’s deeds to his neck, and on the Day of Resurrection We will bring forth for him a record which he will find spread open. ‘Read your record. Today you yourself are sufficient to take account of yourself.’”","[al-Isrāʾ 17:13-14]","And He, the Exalted, says:","“As for the one who is given his record in his right hand, he will say: ‘Here, read my record! Indeed, I was certain that I would meet my reckoning.’ So he will be in a pleasing life…”","Until His statement:","“But as for the one who is given his record in his left hand, he will say: ‘If only I had not been given my record, and had never known what my reckoning was! If only death had been the end! My wealth has not benefited me. My authority has vanished from me.’”","[al-Ḥāqqah 69:19-29]","And He, the Exalted, says:","“As for the one who is given his record in his right hand, he will receive an easy reckoning and return joyfully to his people. But as for the one who is given his record from behind his back, he will cry out for destruction and enter a blazing Fire. Indeed, he had lived joyfully among his people. He thought that he would never return. But yes! Indeed, his Lord was always seeing him.”","[al-Inshiqāq 84:7-15]"]},"n16216":{"a":["قال تعالى:","﴿وَبَدَا لَهُمْ سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ ۝ وَقِيلَ الْيَوْمَ نَنْسَاكُمْ كَمَا نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَذَا وَمَأْوَاكُمُ النَّارُ وَمَا لَكُمْ مِنْ نَاصِرِينَ﴾ [سورة الجاثية: ٣٣-٣٤]."],"b":["আল্লাহ তাআলা বলেন:","“তাদের কৃতকর্মের মন্দ পরিণতি তাদের সামনে প্রকাশ হয়ে পড়বে এবং যা নিয়ে তারা উপহাস করত তা তাদের ঘিরে ফেলবে। আর বলা হবে, ‘আজ আমি তোমাদের ভুলে যাব, যেমন তোমরা তোমাদের এই দিনের সাক্ষাৎ ভুলে গিয়েছিলে। তোমাদের আশ্রয় আগুন, আর তোমাদের কোনো সাহায্যকারী থাকবে না।’”","[সূরা আল-জাসিয়াহ ৪৫:৩৩–৩৪]"],"e":["Allah, the Exalted, says:","“The evil consequences of what they did will become apparent to them, and what they used to mock will surround them. And it will be said: ‘Today We will forget you just as you forgot the meeting of this Day of yours. Your refuge is the Fire, and you will have no helpers.’”","[al-Jāthiyah 45:33-34]"]},"n16228":{"a":["قال تعالى:","﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ﴾ [سورة الأنبياء: ٤٧].","وقال تعالى:","﴿وَالْوَزْنُ يَوْمَئِذٍ الْحَقُّ فَمَنْ ثَقُلَتْ مَوَازِينُهُ فَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ۝ وَمَنْ خَفَّتْ مَوَازِينُهُ فَأُولَٰئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ بِمَا كَانُوا بِآيَاتِنَا يَظْلِمُونَ﴾ [سورة الأعراف: ٨-٩].","وقال تعالى:","﴿فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ ۝ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ ۝ وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ ۝ فَأُمُّهُ هَاوِيَةٌ ۝ وَمَا أَدْرَاكَ مَا هِيَهْ ۝ نَارٌ حَامِيَةٌ﴾ [سورة القارعة: ٦-١١]."],"b":["আল্লাহ তাআলা বলেন:","“কিয়ামতের দিনের জন্য আমি ন্যায়বিচারের দাঁড়িপাল্লা স্থাপন করব; ফলে কোনো প্রাণীর প্রতি সামান্যও জুলুম করা হবে না। কোনো আমল সরিষার দানার ওজন পরিমাণ হলেও আমি তা উপস্থিত করব। আর হিসাব গ্রহণকারী হিসেবে আমিই যথেষ্ট।”","[সূরা আল-আম্বিয়া ২১:৪৭]","আর তিনি তাআলা বলেন:","“সেদিন ওজন করা হবে সত্যের ভিত্তিতে। যাদের পাল্লা ভারী হবে, তারাই সফলকাম। আর যাদের পাল্লা হালকা হবে, তারাই নিজেদের ক্ষতিগ্রস্ত করেছে, কারণ তারা আমার নিদর্শনসমূহের প্রতি অন্যায় করত।”","[সূরা আল-আ‘রাফ ৭:৮–৯]","আর তিনি তাআলা বলেন:","“যার পাল্লা ভারী হবে, সে থাকবে সুখময় জীবনে। আর যার পাল্লা হালকা হবে, তার আশ্রয় হবে হাবিয়াহ। আর কীসে তোমাকে জানাবে তা কী? তা এক প্রজ্বলিত আগুন।”","[সূরা আল-কারি‘আহ ১০১:৬–১১]"],"e":["Allah, the Exalted, says:","“We will set up the scales of justice for the Day of Resurrection, so no soul will be wronged in the least. Even if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as Reckoners.”","[al-Anbiyāʾ 21:47]","And He, the Exalted, says:","“The weighing on that Day will be the truth. Those whose scales are heavy—it is they who will be successful. And those whose scales are light—it is they who will have lost themselves because they used to wrongfully reject Our signs.”","[al-Aʿrāf 7:8-9]","And He, the Exalted, says:","“As for the one whose scales are heavy, he will be in a pleasant life. But as for the one whose scales are light, his refuge will be the Abyss. And what can make you know what it is? A blazing Fire.”","[al-Qāriʿah 101:6-11]"]},"n16233":{"a":["قال تعالى:","﴿قُلْ هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا ۝ الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا ۝ أُولَٰئِكَ الَّذِينَ كَفَرُوا بِآيَاتِ رَبِّهِمْ وَلِقَائِهِ فَحَبِطَتْ أَعْمَالُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾ [سورة الكهف: ١٠٣-١٠٥]."],"b":["আল্লাহ তাআলা বলেন:","“বলুন, আমি কি তোমাদের জানাব কর্মে সবচেয়ে বেশি ক্ষতিগ্রস্ত কারা? তারা হলো তারা, যাদের দুনিয়ার জীবনের সব প্রচেষ্টা ব্যর্থ হয়েছে, অথচ তারা মনে করত যে তারা ভালো কাজ করছে। তারাই তাদের রবের নিদর্শনসমূহ এবং তাঁর সঙ্গে সাক্ষাৎকে অস্বীকার করেছে; ফলে তাদের আমলসমূহ নিষ্ফল হয়ে গেছে। তাই কিয়ামতের দিনে আমি তাদের কোনো ওজনই দেব না।”","[সূরা আল-কাহফ ১৮:১০৩–১০৫]"],"e":["Allah, the Exalted, says:","“Say: Shall We inform you of those who are the greatest losers in their deeds? They are those whose efforts in the life of this world have gone astray while they thought they were doing good. Those are the ones who disbelieved in the signs of their Lord and in meeting Him, so their deeds became worthless, and We will assign no weight to them on the Day of Resurrection.”","[al-Kahf 18:103-105]"]},"n16234":{"a":["قال تعالى:","﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ [الكوثر: ١]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই আমি আপনাকে আল-কাওসার দান করেছি।”","[সূরা আল-কাওসার ১০৮:১]"],"e":["Allah, the Exalted, says:","“Indeed, We have granted you al-Kawthar.”","[al-Kawthar 108:1]"]},"n16243":{"a":["قال تعالى:","﴿الَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُولَٰئِكَ شَرٌّ مَكَانًا وَأَضَلُّ سَبِيلًا﴾ [سورة الفرقان: ٣٤]."],"b":["আল্লাহ তাআলা বলেন:","“যাদের মুখের ওপর ভর দিয়ে জাহান্নামের দিকে সমবেত করা হবে—তারাই অবস্থানের দিক থেকে নিকৃষ্টতম এবং পথের দিক থেকে সবচেয়ে বেশি বিপথগামী।”","[সূরা আল-ফুরকান ২৫:৩৪]"],"e":["Allah, the Exalted, says:","“Those who will be gathered upon their faces toward Hell—those are in the worst place and are furthest astray from the path.”","[al-Furqān 25:34]"]},"n16244":{"a":["قال تعالى:","﴿يَوْمَ تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ يَسْعَىٰ نُورُهُمْ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ بُشْرَاكُمُ الْيَوْمَ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ۝ يَوْمَ يَقُولُ الْمُنَافِقُونَ وَالْمُنَافِقَاتُ لِلَّذِينَ آمَنُوا انْظُرُونَا نَقْتَبِسْ مِنْ نُورِكُمْ قِيلَ ارْجِعُوا وَرَاءَكُمْ فَالْتَمِسُوا نُورًا فَضُرِبَ بَيْنَهُمْ بِسُورٍ لَهُ بَابٌ بَاطِنُهُ فِيهِ الرَّحْمَةُ وَظَاهِرُهُ مِنْ قِبَلِهِ الْعَذَابُ ۝ يُنَادُونَهُمْ أَلَمْ نَكُنْ مَعَكُمْ قَالُوا بَلَىٰ وَلَٰكِنَّكُمْ فَتَنْتُمْ أَنْفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ الْأَمَانِيُّ حَتَّىٰ جَاءَ أَمْرُ اللَّهِ وَغَرَّكُمْ بِاللَّهِ الْغَرُورُ ۝ فَالْيَوْمَ لَا يُؤْخَذُ مِنْكُمْ فِدْيَةٌ وَلَا مِنَ الَّذِينَ كَفَرُوا مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ وَبِئْسَ الْمَصِيرُ﴾ [سورة الحديد: ١٢-١٥].","وقال تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَىٰ رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ يَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ يَقُولُونَ رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾ [التحريم: ٨]."],"b":["আল্লাহ তাআলা বলেন:","“যেদিন আপনি মুমিন পুরুষ ও মুমিন নারীদের দেখবেন—তাদের নূর তাদের সামনে ও ডান পাশে চলতে থাকবে। বলা হবে, ‘আজ তোমাদের জন্য সুসংবাদ—এমন জান্নাতসমূহ, যার নিচ দিয়ে নদী প্রবাহিত হয়; সেখানে তোমরা চিরকাল থাকবে। এটাই মহাসাফল্য।’","সেদিন মুনাফিক পুরুষ ও মুনাফিক নারীরা মুমিনদের বলবে, ‘আমাদের জন্য অপেক্ষা করো, যাতে আমরা তোমাদের নূর থেকে কিছু গ্রহণ করতে পারি।’ বলা হবে, ‘তোমরা পেছনে ফিরে যাও এবং নূর খোঁজো।’ তারপর তাদের মাঝে একটি প্রাচীর স্থাপন করা হবে, যাতে একটি দরজা থাকবে। তার ভেতরে থাকবে রহমত, আর বাইরে থাকবে শাস্তি।","তারা তাদের ডেকে বলবে, ‘আমরা কি তোমাদের সঙ্গে ছিলাম না?’ তারা বলবে, ‘হ্যাঁ, কিন্তু তোমরা নিজেদের ফিতনায় ফেলেছিলে, অপেক্ষা করেছিলে, সন্দেহ করেছিলে এবং মিথ্যা আশা তোমাদের প্রতারিত করেছিল—অবশেষে আল্লাহর আদেশ এসে গেল; আর প্রতারক তোমাদের আল্লাহ সম্পর্কে প্রতারিত করেছিল।","অতএব আজ তোমাদের কাছ থেকে কোনো মুক্তিপণ গ্রহণ করা হবে না, আর যারা কুফর করেছে তাদের কাছ থেকেও নয়। তোমাদের আশ্রয় আগুন; এটাই তোমাদের উপযুক্ত আবাস, আর কত নিকৃষ্ট গন্তব্য!’”","[সূরা আল-হাদীদ ৫৭:১২–১৫]","আর তিনি তাআলা বলেন:","“হে ঈমানদারগণ! তোমরা আল্লাহর কাছে খাঁটি তাওবা করো। আশা করা যায়, তোমাদের রব তোমাদের পাপসমূহ মোচন করবেন এবং তোমাদের এমন জান্নাতে প্রবেশ করাবেন যার নিচ দিয়ে নদী প্রবাহিত হয়—সেদিন আল্লাহ নবীকে এবং তাঁর সঙ্গে যারা ঈমান এনেছে তাদের লাঞ্ছিত করবেন না। তাদের নূর তাদের সামনে ও ডান পাশে চলতে থাকবে। তারা বলবে, ‘হে আমাদের রব! আমাদের জন্য আমাদের নূর পূর্ণ করে দিন এবং আমাদের ক্ষমা করুন। নিশ্চয়ই আপনি সবকিছুর ওপর ক্ষমতাবান।’”","[সূরা আত-তাহরীম ৬৬:৮]"],"e":["Allah, the Exalted, says:","“On the Day you will see the believing men and believing women, their light proceeding before them and on their right: ‘Glad tidings for you today—Gardens beneath which rivers flow, remaining therein forever. That is the tremendous success.’","On that Day the hypocrite men and hypocrite women will say to those who believed: ‘Wait for us so that we may take some of your light.’ It will be said: ‘Go back behind you and seek light.’ Then a wall containing a gate will be placed between them. Inside it will be mercy, while outside it will be punishment.","They will call to them: ‘Were we not with you?’ They will reply: ‘Yes, but you put yourselves into temptation, waited, doubted, and false hopes deceived you until the command of Allah came, and the deceiver deceived you concerning Allah.","So today no ransom will be accepted from you or from those who disbelieved. Your refuge is the Fire. It is your proper abode, and what a wretched destination.’”","[al-Ḥadīd 57:12-15]","And He, the Exalted, says:","“O you who believe, turn to Allah in sincere repentance. Perhaps your Lord will remove your sins from you and admit you into Gardens beneath which rivers flow, on the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right. They will say: ‘Our Lord, perfect our light for us and forgive us. Indeed, You are capable of all things.’”","[al-Taḥrīm 66:8]"]},"n16257":{"a":["قال اللّٰه تعالى:","﴿وَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ﴾ [آل عمران: ١٣٣].","وقال تعالى:","﴿سَابِقُوا إِلَىٰ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ﴾ [الحديد: ٢١]."],"b":["আল্লাহ তাআলা বলেন:","“তোমরা তোমাদের রবের ক্ষমা এবং এমন জান্নাতের দিকে দ্রুত এগিয়ে যাও, যার বিস্তৃতি আসমানসমূহ ও যমীনের সমান; তা মুত্তাকীদের জন্য প্রস্তুত করা হয়েছে।”","[সূরা আলে ইমরান ৩:১৩৩]","আর তিনি তাআলা বলেন:","“তোমরা তোমাদের রবের ক্ষমা এবং এমন জান্নাতের দিকে প্রতিযোগিতা করো, যার প্রশস্ততা আসমান ও যমীনের প্রশস্ততার মতো; তা প্রস্তুত করা হয়েছে তাদের জন্য যারা আল্লাহ ও তাঁর রাসূলদের প্রতি ঈমান আনে। এটি আল্লাহর অনুগ্রহ; তিনি যাকে ইচ্ছা তা দান করেন। আর আল্লাহ মহাঅনুগ্রহের অধিকারী।”","[সূরা আল-হাদীদ ৫৭:২১]"],"e":["Allah, the Exalted, says:","“Hasten toward forgiveness from your Lord and a Paradise as vast as the heavens and the earth, prepared for the righteous.”","[Āl ʿImrān 3:133]","And He, the Exalted, says:","“Race toward forgiveness from your Lord and a Paradise whose breadth is like the breadth of the heaven and the earth, prepared for those who believe in Allah and His Messengers. That is the bounty of Allah, which He grants to whomever He wills. And Allah is the Possessor of tremendous bounty.”","[al-Ḥadīd 57:21]"]},"n16259":{"a":["قال اللّٰه تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾ [سورة الزمر: ٧٣]."],"b":["আল্লাহ তাআলা বলেন:","“যারা তাদের রবকে ভয় করেছিল, তাদের দলে দলে জান্নাতের দিকে নিয়ে যাওয়া হবে। অবশেষে যখন তারা সেখানে পৌঁছবে এবং তার দরজাসমূহ খুলে দেওয়া হবে, তখন তার প্রহরীরা তাদের বলবে, ‘তোমাদের ওপর শান্তি বর্ষিত হোক। তোমরা উত্তম কাজ করেছ। অতএব চিরকাল থাকার জন্য এতে প্রবেশ করো।’”","[সূরা আয-যুমার ৩৯:৭৩]"],"e":["Allah, the Exalted, says:","“Those who feared their Lord will be driven to Paradise in groups, until when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[al-Zumar 39:73]"]},"n16270":{"a":["قال اللّٰه تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾ [سورة الزمر: ٧٣]."],"b":["আল্লাহ তাআলা বলেন:","“যারা তাদের রবকে ভয় করেছিল, তাদের দলে দলে জান্নাতের দিকে নিয়ে যাওয়া হবে। অবশেষে যখন তারা সেখানে পৌঁছবে এবং তার দরজাসমূহ খুলে দেওয়া হবে, তখন তার প্রহরীরা তাদের বলবে, ‘তোমাদের ওপর শান্তি বর্ষিত হোক। তোমরা উত্তম কাজ করেছ। অতএব চিরকাল থাকার জন্য এতে প্রবেশ করো।’”","[সূরা আয-যুমার ৩৯:৭৩]"],"e":["Allah, the Exalted, says:","“Those who feared their Lord will be driven to Paradise in groups, until when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[al-Zumar 39:73]"]},"n16271":{"a":["قال اللّٰه تعالى:","﴿لَكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ غُرَفٌ مِنْ فَوْقِهَا غُرَفٌ مَبْنِيَّةٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾ [الزمر: ٢٠].","وقال تعالى:","﴿وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُبَوِّئَنَّهُمْ مِنَ الْجَنَّةِ غُرَفًا تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نِعْمَ أَجْرُ الْعَامِلِينَ﴾ [العنكبوت: ٥٨]."],"b":["আল্লাহ তাআলা বলেন:","“কিন্তু যারা তাদের রবকে ভয় করেছে, তাদের জন্য থাকবে সুউচ্চ কক্ষ; তার ওপরও নির্মিত থাকবে আরও কক্ষ, যার নিচ দিয়ে নদী প্রবাহিত হবে। এটি আল্লাহর প্রতিশ্রুতি; আর আল্লাহ তাঁর প্রতিশ্রুতি ভঙ্গ করেন না।”","[সূরা আয-যুমার ৩৯:২০]","আর তিনি তাআলা বলেন:","“যারা ঈমান আনে ও সৎকর্ম করে, আমি অবশ্যই তাদের জান্নাতের সুউচ্চ কক্ষে স্থান দেব, যার নিচ দিয়ে নদী প্রবাহিত হবে; সেখানে তারা চিরকাল থাকবে। কতই না উত্তম সৎকর্মশীলদের প্রতিদান!”","[সূরা আল-আনকাবূত ২৯:৫৮]"],"e":["Allah, the Exalted, says:","“But those who feared their Lord will have lofty chambers, with other chambers built above them, beneath which rivers flow. This is the promise of Allah, and Allah never fails in His promise.”","[al-Zumar 39:20]","And He, the Exalted, says:","“Those who believe and perform righteous deeds, We will surely settle them in lofty chambers of Paradise beneath which rivers flow, remaining therein forever. Excellent indeed is the reward of those who work righteousness.”","[al-ʿAnkabūt 29:58]"]},"n16277":{"a":["قال اللّٰه تعالى:","﴿حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِ﴾ [الرحمن: ٧٢].","وقال تعالى:","﴿وَيُطَافُ عَلَيْهِمْ بِآنِيَةٍ مِنْ فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا ۝ قَوَارِيرَ مِنْ فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا ۝ وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنْجَبِيلًا ۝ عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا﴾ [الإنسان: ١٥-١٨].","وقال تعالى:","﴿يُطَافُ عَلَيْهِمْ بِصِحَافٍ مِنْ ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ الْأَنْفُسُ وَتَلَذُّ الْأَعْيُنُ وَأَنْتُمْ فِيهَا خَالِدُونَ﴾ [الزخرف: ٧١].","وقال تعالى:","﴿يَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُخَلَّدُونَ ۝ بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِنْ مَعِينٍ﴾ [سورة الواقعة: ١٧-١٨]."],"b":["আল্লাহ তাআলা বলেন:","“তাঁবুসমূহে আবদ্ধ সুন্দরী নারীগণ।”","[সূরা আর-রহমান ৫৫:৭২]","আর তিনি তাআলা বলেন:","“তাদের চারপাশে রূপার পাত্র ও স্ফটিকের পেয়ালা নিয়ে পরিবেশন করা হবে—রূপার স্ফটিক, যা যথাযথ মাপে নির্ধারিত। আর সেখানে তাদের এমন পেয়ালা থেকে পান করানো হবে, যার মিশ্রণ হবে আদা; এমন এক ঝরনা থেকে, যার নাম সালসাবীল।”","[সূরা আল-ইনসান ৭৬:১৫–১৮]","আর তিনি তাআলা বলেন:","“তাদের সামনে স্বর্ণের থালা ও পেয়ালা পরিবেশন করা হবে; আর সেখানে থাকবে যা কিছু মন চায় ও চোখ উপভোগ করে; এবং তোমরা সেখানে চিরকাল থাকবে।”","[সূরা আয-যুখরুফ ৪৩:৭১]","আর তিনি তাআলা বলেন:","“চিরকিশোররা তাদের চারপাশে ঘুরে বেড়াবে—পেয়ালা, জগ এবং প্রবাহমান ঝরনার পানপাত্র নিয়ে।”","[সূরা আল-ওয়াকি‘আহ ৫৬:১৭–১৮]"],"e":["Allah, the Exalted, says:","“Fair maidens secluded in pavilions.”","[al-Raḥmān 55:72]","And He, the Exalted, says:","“They will be served with vessels of silver and cups that are crystal—crystal of silver, measured precisely. And they will be given to drink therein from a cup whose mixture is ginger, from a spring therein called Salsabīl.”","[al-Insān 76:15-18]","And He, the Exalted, says:","“They will be served with dishes and cups of gold, and therein will be whatever the souls desire and the eyes delight in, and you will remain therein forever.”","[al-Zukhruf 43:71]","And He, the Exalted, says:","“Immortal youths will circulate among them with cups, pitchers, and a goblet from a flowing spring.”","[al-Wāqiʿah 56:17-18]"]},"n16300":{"a":["قال الله تعالى:","﴿أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَهُمْ دَرَجَاتٌ عِنْدَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ﴾ [الأنفال: ٤].","وقال تعالى:","﴿الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ﴾ [سورة المؤمنون: ١١]."],"b":["আল্লাহ তাআলা বলেন:","“তারাই সত্যিকার মুমিন। তাদের জন্য তাদের রবের কাছে রয়েছে মর্যাদার স্তরসমূহ, ক্ষমা এবং সম্মানজনক রিযিক।”","[সূরা আল-আনফাল ৮:৪]","আর তিনি তাআলা বলেন:","“যারা ফিরদাউসের উত্তরাধিকারী হবে; তারা সেখানে চিরকাল থাকবে।”","[সূরা আল-মু’মিনূন ২৩:১১]"],"e":["Allah, the Exalted, says:","“Those are the true believers. For them are ranks with their Lord, forgiveness, and a noble provision.”","[al-Anfāl 8:4]","And He, the Exalted, says:","“Those who will inherit al-Firdaws; they will remain therein forever.”","[al-Muʾminūn 23:11]"]},"n16311":{"a":["قال تعالى:","﴿وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ كُلَّمَا رُزِقُوا مِنْهَا مِنْ ثَمَرَةٍ رِزْقًا قَالُوا هَٰذَا الَّذِي رُزِقْنَا مِنْ قَبْلُ وَأُتُوا بِهِ مُتَشَابِهًا وَلَهُمْ فِيهَا أَزْوَاجٌ مُطَهَّرَةٌ وَهُمْ فِيهَا خَالِدُونَ﴾ [سورة البقرة: ٢٥].","وقال تعالى:","﴿فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ﴾ [سورة الرحمن: ٦٨]."],"b":["আল্লাহ তাআলা বলেন:","“যারা ঈমান আনে ও সৎকর্ম করে তাদের সুসংবাদ দিন যে তাদের জন্য রয়েছে জান্নাতসমূহ, যার নিচ দিয়ে নদী প্রবাহিত হয়। যখনই সেখান থেকে তাদের ফল খেতে দেওয়া হবে, তারা বলবে, ‘এ তো সেই জিনিস যা আগে আমাদের দেওয়া হয়েছিল।’ আর তাদের একই রকম দেখতে ফল দেওয়া হবে। সেখানে তাদের জন্য থাকবে পবিত্র সঙ্গী, এবং তারা সেখানে চিরকাল থাকবে।”","[সূরা আল-বাকারাহ ২:২৫]","আর তিনি তাআলা বলেন:","“উভয়ের মধ্যে থাকবে ফলমূল, খেজুরগাছ ও ডালিম।”","[সূরা আর-রহমান ৫৫:৬৮]"],"e":["Allah, the Exalted, says:","“Give glad tidings to those who believe and perform righteous deeds that they will have Gardens beneath which rivers flow. Whenever they are provided with fruit from them, they will say: ‘This is what we were provided with before,’ and they will be given things resembling one another. They will have purified spouses therein, and they will remain therein forever.”","[al-Baqarah 2:25]","And He, the Exalted, says:","“In both of them are fruits, date-palms, and pomegranates.”","[al-Raḥmān 55:68]"]},"n16321":{"a":["قال تعالى:","﴿وَلَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَ﴾ [الواقعة: ٢١]."],"b":["আল্লাহ তাআলা বলেন:","“আর পাখির মাংস—যা তারা কামনা করবে।”","[সূরা আল-ওয়াকি‘আহ ৫৬:২১]"],"e":["Allah, the Exalted, says:","“And the meat of birds from whatever they desire.”","[al-Wāqiʿah 56:21]"]},"n16322":{"a":["قال تعالى:","﴿مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ فِيهَا أَنْهَارٌ مِنْ مَاءٍ غَيْرِ آسِنٍ وَأَنْهَارٌ مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُ وَأَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِبِينَ وَأَنْهَارٌ مِنْ عَسَلٍ مُصَفًّى وَلَهُمْ فِيهَا مِنْ كُلِّ الثَّمَرَاتِ وَمَغْفِرَةٌ مِنْ رَبِّهِمْ﴾ [محمد: ١٥]."],"b":["আল্লাহ তাআলা বলেন:","“মুত্তাকীদের প্রতিশ্রুত জান্নাতের দৃষ্টান্ত হলো—সেখানে রয়েছে এমন পানির নদী যার স্বাদ ও গন্ধ পরিবর্তিত হয় না, এমন দুধের নদী যার স্বাদ পরিবর্তিত হয় না, পানকারীদের জন্য সুস্বাদু মদের নদী এবং পরিশোধিত মধুর নদী। সেখানে তাদের জন্য থাকবে সব ধরনের ফল এবং তাদের রবের পক্ষ থেকে ক্ষমা।”","[সূরা মুহাম্মাদ ৪৭:১৫]"],"e":["Allah, the Exalted, says:","“The description of the Paradise promised to the righteous is that in it are rivers of water whose taste and smell do not change, rivers of milk whose taste does not change, rivers of wine delightful to those who drink it, and rivers of purified honey. They will have therein every kind of fruit and forgiveness from their Lord.”","[Muḥammad 47:15]"]},"n16330":{"a":["قال تعالى:","﴿ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَأَزْوَاجُكُمْ تُحْبَرُونَ﴾ [الزخرف: ٧٠].","وقال تعالى:","﴿فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾ [سورة الروم: ١٥].","قوله: ﴿يُحْبَرُونَ﴾ من الحبور، وهو السرور الشديد، يقال: حبره إذا سره سرورًا تهلل به وجهه، وظهر فيه أثره. ومن نعم الجنة أن أهلها يسمعون الصوت الحسن، يتهلل منه وجوههم، ولذا فسر بعض أهل العلم الحبور بسماع الصوت الحسن.","قال يحيى بن أبي كثير، في قوله عز وجل: ﴿فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾ قال: السماع. ومعنى السماع مثل ما ورد في الحديث أن الحور العين يرفعن بأصواتهن. رواه الترمذي (٢٥٦٥)."],"b":["আল্লাহ তাআলা বলেন:","“তোমরা ও তোমাদের স্ত্রীগণ আনন্দিত অবস্থায় জান্নাতে প্রবেশ করো।”","[সূরা আয-যুখরুফ ৪৩:৭০]","আর তিনি তাআলা বলেন:","“আর যারা ঈমান এনেছে ও সৎকর্ম করেছে, তারা বাগানে আনন্দিত থাকবে।”","[সূরা আর-রূম ৩০:১৫]","‘ইউহবারূন’ শব্দটি ‘হুবূর’ থেকে এসেছে, যার অর্থ প্রবল আনন্দ। বলা হয়, ‘সে তাকে আনন্দিত করেছে,’ যখন সে তাকে এমন আনন্দ দেয় যে তার মুখমণ্ডল উজ্জ্বল হয়ে ওঠে এবং সেই আনন্দের প্রভাব তার ওপর প্রকাশ পায়।","জান্নাতের নিয়ামতসমূহের একটি হলো—সেখানকার অধিবাসীরা সুন্দর কণ্ঠস্বর শুনবে, যা আনন্দে তাদের মুখ উজ্জ্বল করে তুলবে। এ কারণেই কিছু আলিম ‘হুবূর’-এর ব্যাখ্যা করেছেন সুন্দর কণ্ঠস্বর শোনা হিসেবে।","ইয়াহইয়া ইবন আবী কাসীর আল্লাহ মহাপরাক্রমশালী ও মহিমান্বিতের বাণী—","“তারা বাগানে আনন্দিত থাকবে”—","সম্পর্কে বলেছেন, এর অর্থ হলো শ্রবণ।","এই শ্রবণের অর্থ সেই হাদীসে বর্ণিত বিষয়ের মতো, যেখানে এসেছে যে হূর আল-ঈন সুরেলা কণ্ঠে গান করবে। এটি বর্ণনা করেছেন আত-তিরমিযী (২৫৬৫)।"],"e":["Allah, the Exalted, says:","“Enter Paradise, you and your spouses, rejoicing.”","[al-Zukhruf 43:70]","And He, the Exalted, says:","“As for those who believed and performed righteous deeds, they will be rejoicing in a garden.”","[al-Rūm 30:15]","The word “yuḥbarūn” comes from ḥubūr, meaning intense joy. It is said, “He delighted him,” when he brought him such joy that his face became radiant and the effect of that joy became visible upon him.","Among the blessings of Paradise is that its people will hear beautiful voices that cause their faces to brighten with delight. For this reason, some scholars interpreted ḥubūr as hearing beautiful voices.","Yaḥyā ibn Abī Kathīr said concerning the statement of Allah, Mighty and Majestic:","“They will be rejoicing in a garden,”","that it means hearing.","The meaning of this hearing is like what is mentioned in the hadith that the ḥūr al-ʿīn will raise their voices in song. Narrated by al-Tirmidhī (2565)."]},"n16332":{"a":["قال تعالى:","﴿إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ﴾ [الحج: ٢٣].","وقال تعالى:","﴿أُولَٰئِكَ لَهُمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِنْ سُنْدُسٍ وَإِسْتَبْرَقٍ مُتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ نِعْمَ الثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا﴾ [الكهف: ٣١]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা ঈমান আনে ও সৎকর্ম করে, আল্লাহ তাদের এমন জান্নাতে প্রবেশ করাবেন যার নিচ দিয়ে নদী প্রবাহিত হয়। সেখানে তাদের সোনার কংকন ও মুক্তা দিয়ে অলংকৃত করা হবে, আর সেখানে তাদের পোশাক হবে রেশমের।”","[সূরা আল-হজ্জ ২২:২৩]","আর তিনি তাআলা বলেন:","“তাদের জন্য রয়েছে চিরস্থায়ী জান্নাতসমূহ, যার নিচ দিয়ে নদী প্রবাহিত হয়। সেখানে তাদের সোনার কংকন দিয়ে অলংকৃত করা হবে, তারা পরিধান করবে সূক্ষ্ম রেশম ও মোটা রেশমের সবুজ পোশাক, আর সেখানে আসনে হেলান দিয়ে বসবে। কত উত্তম প্রতিদান, এবং কত সুন্দর বিশ্রামস্থল!”","[সূরা আল-কাহফ ১৮:৩১]"],"e":["Allah, the Exalted, says:","“Indeed, Allah will admit those who believe and perform righteous deeds into Gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearls, and their clothing therein will be silk.”","[al-Ḥajj 22:23]","And He, the Exalted, says:","“Those will have Gardens of perpetual residence beneath which rivers flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein upon couches. Excellent is the reward, and beautiful is the resting place.”","[al-Kahf 18:31]"]},"n16373":{"a":["قال الله تعالى:","﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ إِخْوَانًا عَلَىٰ سُرُرٍ مُتَقَابِلِينَ﴾ [الحجر: ٤٧]."],"b":["আল্লাহ তাআলা বলেন:","“আমি তাদের অন্তর থেকে সব বিদ্বেষ দূর করে দেব; ফলে তারা ভাই ভাই হয়ে পরস্পর মুখোমুখি হয়ে আসনে বসবে।”","[সূরা আল-হিজর ১৫:৪৭]"],"e":["Allah, the Exalted, says:","“We will remove whatever resentment is in their hearts, so they will be brothers, facing one another upon couches.”","[al-Ḥijr 15:47]"]},"n16432":{"a":["قال اللّٰه تعالى:","﴿وَحُورٌ عِينٌ ۝ كَأَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ﴾ [سورة الواقعة: ٢٢-٢٣].","وقال تعالى:","﴿وَعِنْدَهُمْ قَاصِرَاتُ الطَّرْفِ أَتْرَابٌ﴾ [سورة ص: ٥٢].","وقال تعالى:","﴿فِيهِنَّ خَيْرَاتٌ حِسَانٌ ۝ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ۝ حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِ ۝ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ۝ لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلَا جَانٌّ﴾ [سورة الرحمن: ٧٠-٧٤].","وقال تعالى:","﴿وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا لَهُمْ فِيهَا أَزْوَاجٌ مُطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾ [سورة النساء: ٥٧]."],"b":["আল্লাহ তাআলা বলেন:","“আর থাকবে ডাগর সুন্দর চোখের হূরগণ, যেন সযত্নে সংরক্ষিত মুক্তা।”","[সূরা আল-ওয়াকি‘আহ ৫৬:২২–২৩]","আর তিনি তাআলা বলেন:","“আর তাদের সঙ্গে থাকবে অবনত দৃষ্টির, সমবয়সী নারীগণ।”","[সূরা সাদ ৩৮:৫২]","আর তিনি তাআলা বলেন:","“সেখানে রয়েছে উত্তম ও সুন্দর নারীগণ। অতএব তোমাদের রবের কোন কোন নিয়ামত তোমরা উভয়ে অস্বীকার করবে? তাঁবুসমূহে আবদ্ধ সুন্দরী নারীগণ। অতএব তোমাদের রবের কোন কোন নিয়ামত তোমরা উভয়ে অস্বীকার করবে? তাদের আগে কোনো মানুষ বা জিন স্পর্শ করেনি।”","[সূরা আর-রহমান ৫৫:৭০–৭৪]","আর তিনি তাআলা বলেন:","“যারা ঈমান আনে ও সৎকর্ম করে, আমি তাদের জান্নাতে প্রবেশ করাব, যার নিচ দিয়ে নদী প্রবাহিত হয়; সেখানে তারা চিরকাল থাকবে। তাদের জন্য সেখানে থাকবে পবিত্র সঙ্গী, এবং আমি তাদের ঘন ছায়ায় প্রবেশ করাব।”","[সূরা আন-নিসা ৪:৫৭]"],"e":["Allah, the Exalted, says:","“And fair women with wide, beautiful eyes, like well-protected pearls.”","[al-Wāqiʿah 56:22-23]","And He, the Exalted, says:","“And with them will be women who restrain their glances, equal in age.”","[Ṣād 38:52]","And He, the Exalted, says:","“In them are good and beautiful women. So which of the favors of your Lord will you both deny? Fair women secluded in pavilions. So which of the favors of your Lord will you both deny? No human or jinn has touched them before.”","[al-Raḥmān 55:70-74]","And He, the Exalted, says:","“Those who believe and perform righteous deeds, We will admit them into Gardens beneath which rivers flow, remaining therein forever. They will have purified spouses therein, and We will admit them into deep shade.”","[al-Nisāʾ 4:57]"]},"n16442":{"a":["قال تعالى:","﴿لَهُمْ مَا يَشَاءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ﴾ [سورة ق: ٣٥].","قوله: ﴿لَهُمْ مَا يَشَاءُونَ فِيهَا﴾ أي: أنهم يجدون فيها جميع أصناف الملاذ، وكلما طلبوا أحضر لهم، قال تعالى:","﴿وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنْفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ﴾ [فصلت: ٣١]."],"b":["আল্লাহ তাআলা বলেন:","“সেখানে তারা যা চাইবে তাই পাবে, আর আমার কাছে রয়েছে আরও বেশি।”","[সূরা ক্বাফ ৫০:৩৫]","তাঁর বাণী—","“সেখানে তারা যা চাইবে তাই পাবে”—","সম্পর্কে লেখক ব্যাখ্যা করেছেন যে তারা সেখানে সব ধরনের আনন্দ পাবে এবং যা কিছু চাইবে, তা তাদের কাছে এনে দেওয়া হবে।","আল্লাহ তাআলা বলেন:","“সেখানে তোমাদের জন্য থাকবে যা কিছু তোমাদের মন চায়, এবং সেখানে তোমাদের জন্য থাকবে যা কিছু তোমরা চাইবে।”","[সূরা ফুসসিলাত ৪১:৩১]"],"e":["Allah, the Exalted, says:","“They will have whatever they wish therein, and with Us is even more.”","[Qāf 50:35]","Regarding His statement:","“They will have whatever they wish therein,”","the author explains that they will find therein every kind of pleasure, and whatever they request will be brought to them.","Allah, the Exalted, says:","“You will have therein whatever your souls desire, and you will have therein whatever you ask for.”","[Fuṣṣilat 41:31]"]},"n16444":{"a":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمَانِهِمْ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ فِي جَنَّاتِ النَّعِيمِ ۝ دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ [سورة يونس: ٩-١٠]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা ঈমান আনে ও সৎকর্ম করে—তাদের রব তাদের ঈমানের কারণে পথনির্দেশ করবেন। নিয়ামতে পরিপূর্ণ জান্নাতে তাদের নিচ দিয়ে নদী প্রবাহিত হবে। সেখানে তাদের দোয়া হবে, ‘হে আল্লাহ! আপনি পবিত্র’; তাদের অভিবাদন হবে, ‘সালাম’; আর তাদের দোয়ার সমাপ্তি হবে, ‘সমস্ত প্রশংসা আল্লাহর জন্য, যিনি সকল জগতের রব।’”","[সূরা ইউনুস ১০:৯–১০]"],"e":["Allah, the Exalted, says:","“Indeed, those who believe and perform righteous deeds—their Lord will guide them by their faith. Rivers will flow beneath them in Gardens of Bliss. Their prayer therein will be: ‘Glory be to You, O Allah,’ and their greeting therein will be: ‘Peace,’ and the conclusion of their prayer will be: ‘All praise belongs to Allah, Lord of the worlds.’”","[Yūnus 10:9-10]"]},"n16449":{"a":["قال الله تعالى:","﴿يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾ [سورة ق: ٣٠]."],"b":["আল্লাহ তাআলা বলেন:","“যেদিন আমি জাহান্নামকে বলব, ‘তুমি কি পূর্ণ হয়েছ?’ আর সে বলবে, ‘আরও আছে কি?’”","[সূরা ক্বাফ ৫০:৩০]"],"e":["Allah, the Exalted, says:","“On the Day We will say to Hell, ‘Are you filled?’ and it will say, ‘Is there any more?’”","[Qāf 50:30]"]},"n16464":{"a":["قال اللّٰه تعالى:","﴿إِنَّ شَجَرَتَ الزَّقُّومِ ۝ طَعَامُ الْأَثِيمِ ۝ كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ ۝ كَغَلْيِ الْحَمِيمِ ۝ خُذُوهُ فَاعْتِلُوهُ إِلَىٰ سَوَاءِ الْجَحِيمِ ۝ ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ﴾ [الدخان: ٤٣-٤٨].","وقال تعالى:","﴿فَلَيْسَ لَهُ الْيَوْمَ هَاهُنَا حَمِيمٌ ۝ وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ ۝ لَا يَأْكُلُهُ إِلَّا الْخَاطِئُونَ﴾ [الحاقة: ٣٥-٣٧].","وقال تعالى:","﴿تَصْلَىٰ نَارًا حَامِيَةً ۝ تُسْقَىٰ مِنْ عَيْنٍ آنِيَةٍ ۝ لَيْسَ لَهُمْ طَعَامٌ إِلَّا مِنْ ضَرِيعٍ ۝ لَا يُسْمِنُ وَلَا يُغْنِي مِنْ جُوعٍ﴾ [الغاشية: ٤-٧]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যাক্কূম গাছ পাপীর খাদ্য। গলিত ধাতুর মতো তা পেটে ফুটবে—উত্তপ্ত পানির মতো ফুটতে থাকবে। ‘তাকে ধরো এবং জ্বলন্ত আগুনের মাঝখানে টেনে নিয়ে যাও। তারপর তার মাথার ওপর ফুটন্ত পানির শাস্তি ঢেলে দাও।’”","[সূরা আদ-দুখান ৪৪:৪৩–৪৮]","আর তিনি তাআলা বলেন:","“আজ এখানে তার কোনো অন্তরঙ্গ বন্ধু নেই এবং কোনো খাদ্যও নেই পুঁজমিশ্রিত নোংরা বস্তু ছাড়া; যা পাপীরা ছাড়া কেউ খাবে না।”","[সূরা আল-হাক্কাহ ৬৯:৩৫–৩৭]","আর তিনি তাআলা বলেন:","“তারা প্রবেশ করবে জ্বলন্ত আগুনে; তাদের ফুটন্ত ঝরনা থেকে পান করানো হবে। তাদের জন্য কাঁটাযুক্ত তিক্ত উদ্ভিদ ছাড়া কোনো খাদ্য থাকবে না, যা পুষ্টি দেয় না এবং ক্ষুধাও নিবারণ করে না।”","[সূরা আল-গাশিয়াহ ৮৮:৪–৭]"],"e":["Allah, the Exalted, says:","“Indeed, the tree of Zaqqūm is the food of the sinful. Like molten metal, it will boil in the bellies like the boiling of scalding water. ‘Seize him and drag him into the midst of the blazing Fire. Then pour over his head the torment of scalding water.’”","[al-Dukhān 44:43-48]","And He, the Exalted, says:","“So today he has no devoted friend here, nor any food except foul discharge, which none will eat except the sinners.”","[al-Ḥāqqah 69:35-37]","And He, the Exalted, says:","“They will enter a blazing Fire, given drink from a boiling spring. They will have no food except from a bitter thorny plant, which neither nourishes nor satisfies hunger.”","[al-Ghāshiyah 88:4-7]"]},"n16479":{"a":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا لَوْ أَنَّ لَهُمْ مَا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ عَذَابِ يَوْمِ الْقِيَامَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ [المائدة: ٣٦]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা কুফর করেছে—যদি তাদের কাছে পৃথিবীর সবকিছু এবং তার সঙ্গে সমপরিমাণ আরও কিছু থাকে, যাতে তারা কিয়ামতের দিনের শাস্তি থেকে নিজেদের মুক্তিপণ দিতে পারে—তবুও তাদের কাছ থেকে তা গ্রহণ করা হবে না; আর তাদের জন্য রয়েছে যন্ত্রণাদায়ক শাস্তি।”","[সূরা আল-মায়িদাহ ৫:৩৬]"],"e":["Allah, the Exalted, says:","“Indeed, those who disbelieve—even if they possessed everything on earth and another equal amount with it to ransom themselves from the punishment of the Day of Resurrection, it would not be accepted from them, and they will have a painful punishment.”","[al-Māʾidah 5:36]"]},"n16482":{"a":["قال الله تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا بِآيَاتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ إِنَّ اللَّهَ كَانَ عَزِيزًا حَكِيمًا﴾ [النساء: ٥٦].","أي تبدل جلودهم لأن الإحساس بالألم مرتبط بالجلود دون اللحوم.","وقد جاء وصف جلود الكفار في النار في الحديث:"],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা আমার নিদর্শনসমূহ অস্বীকার করেছে, আমি তাদের আগুনে পোড়াব। যখনই তাদের চামড়া সম্পূর্ণ পুড়ে যাবে, আমি তা অন্য চামড়া দিয়ে পরিবর্তন করে দেব, যাতে তারা শাস্তি আস্বাদন করে। নিশ্চয়ই আল্লাহ মহাপরাক্রমশালী, প্রজ্ঞাময়।”","[সূরা আন-নিসা ৪:৫৬]","অর্থাৎ তাদের চামড়া পরিবর্তন করা হবে, কারণ ব্যথার অনুভূতি মাংসের পরিবর্তে চামড়ার সঙ্গে সম্পর্কিত।","জাহান্নামে কাফিরদের চামড়ার বর্ণনা হাদীসেও এসেছে:"],"e":["Allah, the Exalted, says:","“Indeed, those who disbelieve in Our signs, We will burn them in a Fire. Whenever their skins are completely burned, We will replace them with other skins so that they may taste the punishment. Indeed, Allah is Almighty, All-Wise.”","[al-Nisāʾ 4:56]","That is, their skins will be replaced because the sensation of pain is connected to the skin rather than the flesh.","The description of the skins of the disbelievers in the Fire has also been mentioned in the hadiths:"]},"n16494":{"a":["قال الله تعالى:","﴿بَشِّرِ الْمُنَافِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا﴾ [النساء: ١٣٨].","وقال:","﴿إِنَّ اللَّهَ جَامِعُ الْمُنَافِقِينَ وَالْكَافِرِينَ فِي جَهَنَّمَ جَمِيعًا﴾ [النساء: ١٤٠].","وقال تعالى:","﴿إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ﴾ [النساء: ١٤٥].","وقال تعالى:","﴿وَعَدَ اللَّهُ الْمُنَافِقِينَ وَالْمُنَافِقَاتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ﴾ [التوبة: ٦٨]."],"b":["আল্লাহ তাআলা বলেন:","“মুনাফিকদের সুসংবাদ দিন যে তাদের জন্য রয়েছে যন্ত্রণাদায়ক শাস্তি।”","[সূরা আন-নিসা ৪:১৩৮]","আর তিনি বলেন:","“নিশ্চয়ই আল্লাহ মুনাফিক ও কাফির সকলকে জাহান্নামে একত্র করবেন।”","[সূরা আন-নিসা ৪:১৪০]","আর তিনি তাআলা বলেন:","“নিশ্চয়ই মুনাফিকরা জাহান্নামের সর্বনিম্ন স্তরে থাকবে।”","[সূরা আন-নিসা ৪:১৪৫]","আর তিনি তাআলা বলেন:","“আল্লাহ মুনাফিক পুরুষ, মুনাফিক নারী এবং কাফিরদের জন্য জাহান্নামের আগুনের প্রতিশ্রুতি দিয়েছেন।”","[সূরা আত-তাওবাহ ৯:৬৮]"],"e":["Allah, the Exalted, says:","“Give the hypocrites tidings that for them is a painful punishment.”","[al-Nisāʾ 4:138]","And He says:","“Indeed, Allah will gather the hypocrites and the disbelievers all together in Hell.”","[al-Nisāʾ 4:140]","And He, the Exalted, says:","“Indeed, the hypocrites will be in the lowest depths of the Fire.”","[al-Nisāʾ 4:145]","And He, the Exalted, says:","“Allah has promised the hypocrite men and hypocrite women, and the disbelievers, the Fire of Hell.”","[al-Tawbah 9:68]"]},"n16524":{"a":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا ۝ خَالِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا﴾ [الكهف: ١٠٧-١٠٨].","وقال تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ۝ خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ﴾ [البقرة: ١٦١-١٦٢]."],"b":["আল্লাহ তাআলা বলেন:","“নিশ্চয়ই যারা ঈমান আনে ও সৎকর্ম করে, তাদের আপ্যায়নের জন্য থাকবে জান্নাতুল ফিরদাউস; সেখানে তারা চিরকাল থাকবে এবং সেখান থেকে স্থানান্তর কামনা করবে না।”","[সূরা আল-কাহফ ১৮:১০৭–১০৮]","আর তিনি তাআলা বলেন:","“নিশ্চয়ই যারা কুফর করেছে এবং কাফির অবস্থায় মৃত্যুবরণ করেছে—তাদের ওপর আল্লাহ, ফেরেশতাগণ এবং সমগ্র মানুষের লা‘নত; সেখানে তারা চিরকাল থাকবে। তাদের শাস্তি হালকা করা হবে না এবং তাদের অবকাশও দেওয়া হবে না।”","[সূরা আল-বাকারাহ ২:১৬১–১৬২]"],"e":["Allah, the Exalted, says:","“Indeed, those who believe and perform righteous deeds will have the Gardens of al-Firdaws as their hospitality, remaining therein forever, never desiring any change from it.”","[al-Kahf 18:107-108]","And He, the Exalted, says:","“Indeed, those who disbelieve and die while they are disbelievers—upon them is the curse of Allah, the angels, and all mankind, remaining therein forever. The punishment will not be lightened for them, nor will they be given respite.”","[al-Baqarah 2:161-162]"]},"n16546":{"a":["قال تعالى:","﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ﴾ [الأنبياء: ٤٧].","يخبر اللّه تعالى عن عدله، وقضائه القسط بين عباده إذا جمعهم يوم القيامة."],"b":["আল্লাহ তাআলা বলেন:","“কিয়ামতের দিনের জন্য আমি ন্যায়বিচারের দাঁড়িপাল্লা স্থাপন করব; ফলে কোনো প্রাণীর প্রতি সামান্যও জুলুম করা হবে না। কোনো আমল সরিষার দানার ওজন পরিমাণ হলেও আমি তা উপস্থিত করব। আর হিসাব গ্রহণকারী হিসেবে আমিই যথেষ্ট।”","[সূরা আল-আম্বিয়া ২১:৪৭]","আল্লাহ তাআলা আমাদের জানিয়েছেন তাঁর পরিপূর্ণ ন্যায়বিচার এবং কিয়ামতের দিনে বান্দাদের একত্র করার পর তাদের মাঝে ন্যায়সঙ্গত ফয়সালার কথা।"],"e":["Allah, the Exalted, says:","“We will set up the scales of justice for the Day of Resurrection, so no soul will be wronged in the least. Even if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as Reckoners.”","[al-Anbiyāʾ 21:47]","Allah, the Exalted, informs us of His perfect justice and His judging with equity between His servants when He gathers them on the Day of Resurrection."]}});